// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.executionimport com.roshan.persona.cognitive.model.UserFeedbackimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.math.maximport kotlin.math.min/** * NOUS — Preference Learner (Module 8 v2 — audit P1 fix). * * Strategy §8: "Feedback loop — user corrections adjust future confidence * thresholds for that topic". * * When the user corrects NOUS ("actually, that's wrong" → NEGATIVE feedback), * the PreferenceLearner: *  1. Extracts the topic from the original query (first significant word). *  2. Increments the correction count for that topic. *  3. If correction rate > 30% (3+ corrections / 10+ queries), lowers the *     confidence threshold for that topic — NOUS will be more cautious *     (TENTATIVE/CAUTIOUS tone) when discussing it in the future. * * ## Topic extraction * * Simple heuristic: takes the query, removes stopwords, picks the first * remaining word as the "topic". A future LLM-based extractor would be more * accurate, but this is sufficient for v1. * * ## Thread safety * * All operations are `@Synchronized`. * * @see ReasoningTraceStore.recordFeedback */@Singletonclass PreferenceLearner @Inject constructor() {    /** Per-topic correction stats. */    private val topicStats = mutableMapOf<String, TopicStats>()    /**     * Record a user feedback event for a topic.     *     * @param query the original user query that led to the trace.     * @param feedback the user's feedback (POSITIVE/NEGATIVE/NEUTRAL).     */    @Synchronized    fun recordFeedback(query: String, feedback: UserFeedback) {        val topic = extractTopic(query) ?: return        val stats = topicStats.getOrPut(topic) { TopicStats(topic) }        stats.totalQueries++        if (feedback == UserFeedback.REJECTED || feedback == UserFeedback.CORRECTED) {            stats.corrections++        }        Timber.tag(TAG).d("Feedback recorded: topic='$topic', feedback=$feedback, corrections=${stats.corrections}/${stats.totalQueries}")    }    /**     * Get the adjusted confidence threshold for a topic.     *     * Returns the standard threshold (0.6) for unknown topics or topics with     * low correction rates. Returns a HIGHER threshold (up to 0.8) for topics     * with high correction rates — NOUS will be more cautious.     *     * @param query the user's current query.     * @param baseThreshold the default threshold (default 0.6).     * @return the adjusted threshold (0.6–0.8).     */    @Synchronized    fun adjustedThreshold(query: String, baseThreshold: Float = 0.6f): Float {        val topic = extractTopic(query) ?: return baseThreshold        val stats = topicStats[topic] ?: return baseThreshold        if (stats.totalQueries < MIN_SAMPLES_FOR_ADJUSTMENT) return baseThreshold        val correctionRate = stats.corrections.toFloat() / stats.totalQueries.toFloat()        return if (correctionRate > CORRECTION_RATE_THRESHOLD) {            // High correction rate → raise threshold (be more cautious).            val adjustment = (correctionRate - CORRECTION_RATE_THRESHOLD) * MAX_ADJUSTMENT            min(baseThreshold + adjustment, MAX_THRESHOLD)        } else {            baseThreshold        }    }    /**     * Get stats for a topic (for UI diagnostics).     */    @Synchronized    fun getTopicStats(topic: String): TopicStats? = topicStats[topic]    /**     * Get all topic stats (for Settings UI).     */    @Synchronized    fun getAllStats(): List<TopicStats> = topicStats.values.toList().sortedByDescending { it.totalQueries }    /** Clear all learned preferences (for tests / user reset). */    @Synchronized    fun clear() {        topicStats.clear()    }    /**     * Extract a "topic" from a user query.     *     * Heuristic: lowercase, remove stopwords, pick first remaining word.     * Returns null if no significant word found.     */    private fun extractTopic(query: String): String? {        val words = query.lowercase()            .split(Regex("\\W+"))            .filter { it.length > 2 && it !in STOPWORDS }        return words.firstOrNull()    }    /** Per-topic correction statistics. */    data class TopicStats(        val topic: String,        var totalQueries: Int = 0,        var corrections: Int = 0,    ) {        /** Correction rate (0.0–1.0). */        val correctionRate: Float get() = if (totalQueries == 0) 0f else corrections.toFloat() / totalQueries    }    private companion object {        private const val TAG = "PreferenceLearner"        /** Minimum samples before adjusting threshold (avoid knee-jerk reactions). */        private const val MIN_SAMPLES_FOR_ADJUSTMENT = 3        /** Correction rate above which threshold is raised (30%). */        private const val CORRECTION_RATE_THRESHOLD = 0.3f        /** Maximum threshold adjustment (0.2 = raise from 0.6 to 0.8 max). */        private const val MAX_ADJUSTMENT = 0.2f        /** Maximum threshold cap. */        private const val MAX_THRESHOLD = 0.8f        /** Common English stopwords to exclude from topic extraction. */        private val STOPWORDS = setOf(            "the", "and", "for", "are", "but", "not", "you", "all", "can", "her",            "was", "one", "our", "out", "his", "how", "what", "when", "who", "why",            "will", "with", "have", "this", "that", "from", "they", "been", "were",            "your", "their", "would", "could", "should", "does", "doing", "done",            "tell", "give", "make", "want", "need", "know", "think", "about",            "into", "some", "them", "than", "then", "very", "just", "also",        )    }}